begin;
do $test$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();roster uuid;room uuid;other_room uuid;empty_roster uuid;empty_room uuid;
 s jsonb;again jsonb;entry jsonb;entry2 jsonb;feed jsonb;results jsonb;question uuid;denied boolean;
 room_name text:='QUICK-'||upper(substr(md5(random()::text),1,10));
begin
 begin
 insert into auth.users(id,email,raw_user_meta_data,is_anonymous) values
 (a,a::text||'@classpulse.invalid','{"full_name":"Quick Teacher A"}',false),
 (b,b::text||'@classpulse.invalid','{"full_name":"Quick Teacher B"}',false);
 execute 'set local role authenticated';perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'is_anonymous',false)::text,true);
 insert into public.rosters(teacher_id,name) values(b,'Other class') returning id into roster;
 insert into public.rooms(teacher_id,roster_id,room_name) values(b,roster,'OTHER-'||upper(substr(md5(random()::text),1,10))) returning id into other_room;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'is_anonymous',false)::text,true);
 insert into public.rosters(teacher_id,name) values(a,'Quick class') returning id into roster;
 perform public.classpulse_import_roster(roster,'[{"id":"001","name":"Mira Devika Rao","emailid":""},{"id":"002","name":"Arjun Mehta","emailid":""}]');
 insert into public.rooms(teacher_id,roster_id,room_name) values(a,roster,room_name) returning id into room;
 denied:=false;begin perform public.classpulse_launch_quick(other_room,'quick_mcq',4,'','other');exception when raise_exception then denied:=true;end;
 if not denied then raise exception 'FAIL: quick launched in another teacher room';end if;
 denied:=false;begin perform public.classpulse_launch_quick(room,'quick_mcq',7,'','invalid');exception when raise_exception then denied:=true;end;
 if not denied then raise exception 'FAIL: invalid option count';end if;
 insert into public.rosters(teacher_id,name) values(a,'Empty quick class') returning id into empty_roster;
 insert into public.rooms(teacher_id,roster_id,room_name) values(a,empty_roster,'EMPTY-'||upper(substr(md5(random()::text),1,10))) returning id into empty_room;
 denied:=false;begin perform public.classpulse_launch_quick(empty_room,'quick_mcq',4,'','empty');exception when raise_exception then denied:=true;end;
 if not denied or exists(select 1 from public.quizzes) then raise exception 'FAIL: empty roster launch or orphan quick record';end if;
 s:=public.classpulse_launch_quick(room,'quick_mcq',4,'','mcq');
 if s->>'activity_type'<>'quick_mcq' or s->>'status'<>'live' then raise exception 'FAIL: quick MCQ launch';end if;
 again:=public.classpulse_launch_quick(room,'quick_mcq',4,'','mcq');
 if again->>'id'<>s->>'id' then raise exception 'FAIL: retry duplicated session';end if;
 if (select count(*) from public.quizzes where source_kind='library')<>0 or (select count(*) from public.quizzes where source_kind='quick')<>1 then raise exception 'FAIL: quick activity library separation';end if;
 denied:=false;begin perform public.classpulse_launch_quick(room,'quick_tf',2,'','occupied');exception when raise_exception then denied:=true;end;
 if not denied then raise exception 'FAIL: active room replaced';end if;
 execute 'reset role';execute 'set local role anon';perform set_config('request.jwt.claims','{}',true);
 entry:=public.classpulse_student_join(room_name,'001');entry2:=public.classpulse_student_join(room_name,'002');
 feed:=public.classpulse_student_question((entry->>'token')::uuid);
 question:=(feed->'question'->>'id')::uuid;
 if feed->>'activity_type'<>'quick_mcq' or jsonb_array_length(feed->'question'->'options')<>4 or feed->'question'->'options'->0->>'label'<>'A' then raise exception 'FAIL: oral MCQ choices';end if;
 perform public.classpulse_submit_answer((entry->>'token')::uuid,question,3,null);
 execute 'reset role';execute 'set local role authenticated';perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'is_anonymous',false)::text,true);
 results:=public.classpulse_live_results((s->>'id')::uuid);
 if results->>'activity_type'<>'quick_mcq' or results->'responses'->0->'is_correct'<>'null'::jsonb or results->'responses'->0->'awarded_points'<>'null'::jsonb then raise exception 'FAIL: ungraded MCQ';end if;
 perform public.classpulse_end_session((s->>'id')::uuid);
 execute 'reset role';execute 'set local role anon';perform set_config('request.jwt.claims','{}',true);
 denied:=false;begin perform public.classpulse_submit_answer((entry2->>'token')::uuid,question,1,null);exception when raise_exception then denied:=true;end;
 if not denied then raise exception 'FAIL: ended poll accepts new response';end if;
 denied:=false;begin perform public.classpulse_launch_quick(room,'quick_tf',2,'','student');exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'FAIL: student launches quick activity';end if;
 execute 'reset role';execute 'set local role authenticated';perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'is_anonymous',false)::text,true);
 s:=public.classpulse_launch_quick(room,'quick_tf',2,'Cash is an asset.','tf');
 execute 'reset role';execute 'set local role anon';perform set_config('request.jwt.claims','{}',true);
 entry:=public.classpulse_student_join(room_name,'001');feed:=public.classpulse_student_question((entry->>'token')::uuid);
 if feed->'question'->'options'->1->>'label'<>'False' then raise exception 'FAIL: TF choices';end if;
 perform public.classpulse_submit_answer((entry->>'token')::uuid,(feed->'question'->>'id')::uuid,2,null);
 execute 'reset role';execute 'set local role authenticated';perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'is_anonymous',false)::text,true);
 perform public.classpulse_end_session((s->>'id')::uuid);
 s:=public.classpulse_launch_quick(room,'word_cloud',0,'Name an asset.','cloud');
 execute 'reset role';execute 'set local role anon';perform set_config('request.jwt.claims','{}',true);
 entry:=public.classpulse_student_join(room_name,'001');feed:=public.classpulse_student_question((entry->>'token')::uuid);question:=(feed->'question'->>'id')::uuid;
 if feed->>'activity_type'<>'word_cloud' or feed->'question'->>'type'<>'short_answer' then raise exception 'FAIL: cloud feed';end if;
 denied:=false;begin perform public.classpulse_submit_answer((entry->>'token')::uuid,question,null,repeat('x',81));exception when raise_exception then denied:=true;end;
 if not denied then raise exception 'FAIL: word cloud character limit';end if;
 denied:=false;begin perform public.classpulse_submit_answer_v1((entry->>'token')::uuid,question,null,repeat('x',81));exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'FAIL: old RPC bypass';end if;
 perform public.classpulse_submit_answer((entry->>'token')::uuid,question,null,' Cash ');
 perform public.classpulse_submit_answer((entry->>'token')::uuid,question,null,'Cash');
 execute 'reset role';execute 'set local role authenticated';perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'is_anonymous',false)::text,true);
 denied:=false;begin perform public.classpulse_live_results((s->>'id')::uuid);exception when raise_exception then denied:=true;end;
 if not denied then raise exception 'FAIL: other teacher cloud access';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'is_anonymous',false)::text,true);
 results:=public.classpulse_live_results((s->>'id')::uuid);
 if jsonb_array_length(results->'responses')<>1 or results->'responses'->0->>'answer_text'<>'Cash' then raise exception 'FAIL: cloud response saving or retry';end if;
 perform public.classpulse_end_session((s->>'id')::uuid);
 if public.classpulse_live_results((s->>'id')::uuid)->>'status'<>'ended' then raise exception 'FAIL: ended quick results lost';end if;
 execute 'reset role';
 raise exception using errcode='CP001',message='Rollback successful quick fixtures';
 exception when sqlstate 'CP001' then null;
 end;
 if exists(select 1 from auth.users where id in(a,b)) then raise exception 'FAIL: fixture cleanup';end if;
end $test$;
rollback;
select 'PASS: quick questions, ungraded responses, word cloud limits and privacy verified; fixtures rolled back' as result;
